String normalizeFontFamilyForFontMetrics(String fontFamily) {
  final packageSeparator = fontFamily.lastIndexOf('/');
  final unprefixed = packageSeparator < 0
      ? fontFamily
      : fontFamily.substring(packageSeparator + 1);
  final withoutGoogleFontsVariant = unprefixed.replaceFirst(
    RegExp(r'_(regular|italic|[1-9]00(?:italic)?)$'),
    '',
  );
  return withoutGoogleFontsVariant
      .replaceAll(RegExp('[^A-Za-z0-9]'), '')
      .toLowerCase();
}

/// Raw raster x-height for a font family, when known.
///
/// Useful for matching monospace/code text to surrounding prose; that
/// use case should generally prefer x-height over role visual-height.
double? rasterXHeightEmForFontFamily(String? fontFamily) {
  if (fontFamily == null) return null;
  return kRasterXHeightEmByFontFamily[normalizeFontFamilyForFontMetrics(
    fontFamily,
  )];
}

double? rasterCapHeightEmForFontFamily(String? fontFamily) {
  if (fontFamily == null) return null;
  return kRasterCapHeightEmByFontFamily[normalizeFontFamilyForFontMetrics(
    fontFamily,
  )];
}

/// Ascent from the font's hhea table, in em, when known.
double? ascentEmForFontFamily(String? fontFamily) {
  if (fontFamily == null) return null;
  return kAscentEmByFontFamily[normalizeFontFamilyForFontMetrics(fontFamily)];
}

/// Descent from the font's hhea table, in em, when known.
double? descentEmForFontFamily(String? fontFamily) {
  if (fontFamily == null) return null;
  return kDescentEmByFontFamily[normalizeFontFamilyForFontMetrics(fontFamily)];
}

double? rasterAveragePhraseCharacterAdvanceEmForFontFamily(String? fontFamily) {
  if (fontFamily == null) return null;
  return kRasterAveragePhraseCharacterAdvanceEmByFontFamily[normalizeFontFamilyForFontMetrics(
    fontFamily,
  )];
}

double? rasterVisualHeightEmForFontFamily(String? fontFamily) {
  if (fontFamily == null) return null;
  return kRasterVisualHeightEmByFontFamily[normalizeFontFamilyForFontMetrics(
    fontFamily,
  )];
}

/// Scale for normal text-theme roles relative to the reference font.
///
/// Uses a composite font-height metric based on rendered phrase height,
/// x-height, and average phrase character advance. Intended for
/// display/headline/body/label role sizing, not for matching monospace
/// code to prose.
double visualHeightScaleForFontFamily(String? fontFamily) {
  final visualHeightEm = rasterVisualHeightEmForFontFamily(fontFamily);
  if (visualHeightEm == null || visualHeightEm <= 0) return 1.0;
  return kReferenceRasterVisualHeightEm / visualHeightEm;
}
